Given n points on a line numbered from 1 to n, and a list of intervals, where each interval [l, r, count] adds count to every point from l to r (inclusive). Compute the total count at each point after processing all intervals.Examples:Input : n = 5, intervals[] = [[1, 2, 9], [2, 4, 5], [3, 5, 7]]Output : [9, 14, 12, 12, 7]Explanation:  Points:                  1   2   3   4   5 Interval [1,2,9]:    9  9    Interval [2,4,5]:       5   5   5 Interval [3,5,7]:              7   7   7 Total count:        9  14  12  12   7Input : n = 4, intervals[] = [[1, 3, 2], [2, 4, 3]]Output : [2, 5, 5, 3]Explanation:  Points:                  1   2   3   4 Interval [1,3,2]:    2   2   2   Interval [2,4,3]:        3   3   3 Total count:         2   5   5   3Table of Content[Naive Approach] Updating Every Point in Each Interval – O(m × n) Time and O(n) Space[Optimized Approach] Using Prefix Contribution – O(n + m) Time and O(n) Space[Naive Approach] Updating Every Point in Each Interval – O(m × n) Time and O(n) SpaceProcess each interval [l, r, count] and add count to every point from l to r in the result array. Initialize an array of size n with 0 and update all elements within each interval.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> intervalContribution(int n, int intervals[][3], int m) {

    vector<int> result(n, 0);

    // Process each interval
    for (int i = 0; i < m; i++) {

        int l = intervals[i][0];
        int r = intervals[i][1];
        int count = intervals[i][2];

        // Update every point in the interval
        for (int j = l - 1; j <= r - 1; j++) {
            result[j] += count;
        }
    }

    return result;
}

int main() {

    int n = 5;

    int intervals[][3] = {
        {1, 2, 9},
        {2, 4, 5},
        {3, 5, 7}
    };

    int m = sizeof(intervals) / sizeof(intervals[0]);

    vector<int> result = intervalContribution(n, intervals, m);

    // Printing result
    for (int i = 0; i < n; i++) {
        cout << result[i] << " ";
    }

    return 0;
}


