            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> intervalContribution(int n, int intervals[][3], int m) {

    vector<int> diff(n + 1, 0);

    // Mark start and end of contributions
    for (int i = 0; i < m; i++) {

        int l = intervals[i][0];
        int r = intervals[i][1];
        int count = intervals[i][2];

        diff[l - 1] += count;

        if (r < n)
            diff[r] -= count;
    }

    // Build final result using prefix sum
    vector<int> result(n);
    result[0] = diff[0];

    for (int i = 1; i < n; i++) {
        result[i] = result[i - 1] + diff[i];
    }

    return result;
}

int main() {

    int n = 5;

    int intervals[][3] = {
        {1, 2, 9},
        {2, 4, 5},
        {3, 5, 7}
    };

    int m = sizeof(intervals) / sizeof(intervals[0]);

    vector<int> result = intervalContribution(n, intervals, m);

    // Printing result
    for (int i = 0; i < n; i++) {
        cout << result[i] << " ";
    }

    return 0;
}


